const COUNTRIES = new Set([
  'ALL', 'US', 'GB', 'DE', 'FR', 'ES', 'IT', 'NL', 'ME', 'RS', 'HR', 'BA', 'SI', 'AT', 'CH',
  'SE', 'NO', 'DK', 'FI', 'IE', 'PT', 'BE', 'PL', 'CZ', 'SK', 'HU', 'RO', 'BG', 'GR', 'TR',
  'UA', 'CA', 'AU', 'NZ', 'BR', 'MX', 'AR', 'IN', 'JP', 'KR', 'SG', 'AE', 'SA', 'EG', 'ZA', 'IL',
]);
const ACTIVE_STATUSES = new Set(['ACTIVE', 'INACTIVE', 'ALL']);
const MEDIA_TYPES = new Set(['ALL', 'IMAGE', 'VIDEO', 'MEME']);
const COMPLETE_COVERAGE = new Set(['COMPLETE', 'EMPTY']);
const TERMINAL_FAILURES = new Set(['FAILED', 'ABORTED', 'TIMED-OUT']);
const MAX_TARGETS = 25;
const MAX_ROWS = 5000;
const PAGE_SIZE = 1000;

function fail(code) {
  throw new Error(code);
}

function upper(value) {
  return String(value ?? '').trim().toUpperCase();
}

function unique(values) {
  const seen = new Set();
  const output = [];
  for (const raw of values) {
    const value = String(raw ?? '').trim();
    const key = value.toLocaleLowerCase('en-US');
    if (!value || seen.has(key)) continue;
    seen.add(key);
    output.push(value);
  }
  return output;
}

function positiveFinite(value, code, maximum) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0 || parsed > maximum) fail(code);
  return parsed;
}

function boundedInteger(value, code, minimum, maximum) {
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < minimum || parsed > maximum) fail(code);
  return parsed;
}

function parseTarget(value) {
  if (!/^https?:\/\//i.test(value)) {
    if (value.length > 120) fail('INVALID_TARGET_KEYWORD_MAX_120');
    return { kind: 'SEARCH', value };
  }
  let url;
  try { url = new URL(value); } catch { fail('INVALID_TARGET_URL'); }
  const host = url.hostname.toLowerCase();
  if (!(host === 'facebook.com' || host.endsWith('.facebook.com') || host === 'fb.com' || host.endsWith('.fb.com'))) {
    fail('TARGET_URL_MUST_BE_FACEBOOK');
  }
  const path = url.pathname.replace(/\/+$/, '');
  if (path === '/ads/library' || path.startsWith('/ads/library/')) {
    if (!url.searchParams.get('q') && !url.searchParams.get('view_all_page_id')) {
      fail('AD_LIBRARY_URL_REQUIRES_Q_OR_PAGE_ID');
    }
    return { kind: 'START_URL', value: url.toString() };
  }
  if (!path || path === '/') fail('FACEBOOK_PAGE_URL_REQUIRED');
  return { kind: 'PAGE', value: url.toString() };
}

function preflightMetaConfig(raw = {}) {
  const telegramChatId = String(raw.telegramChatId ?? '').trim();
  if (!telegramChatId || telegramChatId === 'REPLACE_WITH_YOUR_CHAT_ID') fail('TELEGRAM_CHAT_ID_NOT_CONFIGURED');

  const targets = unique(String(raw.targets ?? '').split(/[\n,]+/));
  if (!targets.length) fail('AT_LEAST_ONE_TARGET_REQUIRED');
  if (targets.length > MAX_TARGETS) fail('TOO_MANY_TARGETS_MAX_25');
  const parsedTargets = targets.map(parseTarget);

  const country = upper(raw.country || 'US');
  const activeStatus = upper(raw.activeStatus || 'ALL');
  const mediaType = upper(raw.mediaType || 'ALL');
  if (!COUNTRIES.has(country)) fail('INVALID_COUNTRY');
  if (!ACTIVE_STATUSES.has(activeStatus)) fail('INVALID_ACTIVE_STATUS');
  if (!MEDIA_TYPES.has(mediaType)) fail('INVALID_MEDIA_TYPE');

  const maxAdsPerTarget = boundedInteger(raw.maxAdsPerTarget, 'INVALID_MAX_ADS_1_TO_100', 1, 100);
  const maxCostPerRunUsd = positiveFinite(raw.maxCostPerRunUsd, 'INVALID_MAX_COST_GT_0_LTE_5', 5);
  const searchTerms = parsedTargets.filter((target) => target.kind === 'SEARCH').map((target) => target.value);
  const pageUrls = parsedTargets.filter((target) => target.kind === 'PAGE').map((target) => target.value);
  const startUrls = parsedTargets.filter((target) => target.kind === 'START_URL').map((target) => target.value);

  return {
    telegramChatId,
    targets,
    targetCount: targets.length,
    maxCostPerRunUsd,
    actorInput: {
      productLevel: 'CHANGES',
      searchTerms,
      pageUrls,
      startUrls,
      country,
      activeStatus,
      adType: 'ALL',
      mediaType,
      maxAdsPerTarget,
      maxPaginationPages: 20,
      maxDeliveryEvents: MAX_ROWS,
      blockMediaDownloads: true,
      maxNetworkGb: 0.05,
      timeoutSeconds: 900,
      browserFallbackPolicy: 'AUTO_GUARDED',
    },
  };
}

function classifyTerminalRun(run = {}) {
  const status = upper(run.status);
  const runId = String(run.id ?? '');
  const runUrl = runId ? `https://console.apify.com/actors/runs/${runId}` : 'https://console.apify.com/actors/runs';
  if (run.error || !status) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', run, runId, runUrl, reason: 'APIFY_RUN_NODE_ERROR' };
  }
  if (status !== 'SUCCEEDED') {
    return {
      ok: false,
      state: TERMINAL_FAILURES.has(status) ? 'ACTOR_FAILED_OR_ABORTED' : 'WORKFLOW_NODE_FAILED',
      run,
      runId,
      runUrl,
      reason: `ACTOR_STATUS_${status}`,
    };
  }
  if (!run.defaultKeyValueStoreId || !run.defaultDatasetId) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', run, runId, runUrl, reason: 'RUN_STORAGE_IDS_MISSING' };
  }
  return { ok: true, state: 'RUN_SUCCEEDED', run, runId, runUrl };
}

function parseRunSummaryRecord(record = {}, run = {}) {
  const runId = String(run.id ?? '');
  const runUrl = runId ? `https://console.apify.com/actors/runs/${runId}` : 'https://console.apify.com/actors/runs';
  const identity = { run, runId, runUrl };
  const data = record?.data;
  if (record.error || !data || typeof data !== 'object' || Array.isArray(data)) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', ...identity, reason: 'RUN_SUMMARY_MISSING_OR_INVALID' };
  }
  if (Number(data.schemaVersion) < 2) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', ...identity, reason: 'RUN_SUMMARY_SCHEMA_UNSUPPORTED' };
  }
  if (data.runId && run.id && data.runId !== run.id) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', ...identity, reason: 'RUN_SUMMARY_RUN_ID_MISMATCH' };
  }
  const buyerChargeUsd = Number(data?.ppe?.actualBuyerChargeUsd);
  if (!Number.isFinite(buyerChargeUsd) || buyerChargeUsd < 0) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', ...identity, reason: 'AUTHORITATIVE_BUYER_CHARGE_MISSING' };
  }
  if (!Array.isArray(data.targetSummaries) || !Array.isArray(data.targetErrors)) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', ...identity, reason: 'RUN_SUMMARY_TARGET_CONTRACT_MISSING' };
  }
  return { ok: true, state: 'SUMMARY_READY', ...identity, summary: data, buyerChargeUsd };
}

function planDatasetPages(summary, pageSize = PAGE_SIZE) {
  const total = boundedInteger(summary?.outputRows, 'INVALID_SUMMARY_OUTPUT_ROWS', 0, MAX_ROWS);
  const size = boundedInteger(pageSize, 'INVALID_DATASET_PAGE_SIZE', 1, PAGE_SIZE);
  if (total === 0) return [{ offset: 0, limit: 1, expectedRows: 0, emptyProbe: true }];
  return Array.from({ length: Math.ceil(total / size) }, (_, index) => ({
    offset: index * size,
    limit: Math.min(size, total - index * size),
    expectedRows: total,
    emptyProbe: false,
  }));
}

function rowKey(row) {
  const identity = row.adId ?? row.materialFingerprint ?? row.id;
  if (!identity) fail('DATASET_ROW_STABLE_ID_MISSING');
  return `${row.queryId ?? row.searchTarget ?? ''}|${identity}|${upper(row.changeStatus)}`;
}

function sumChangeCounts(targetSummaries) {
  const counts = { NEW: 0, UPDATED: 0, ENDED: 0, UNCHANGED: 0 };
  for (const target of targetSummaries) {
    for (const [name, value] of Object.entries(target?.change?.deliveredCounts ?? {})) {
      const key = upper(name);
      if (Object.hasOwn(counts, key)) counts[key] += Number(value) || 0;
    }
  }
  return counts;
}

function reconcileMetaRun({ run = {}, summary = {}, rows = [], expectedTargetCount }) {
  const runId = String(run.id ?? summary.runId ?? '');
  const runUrl = runId ? `https://console.apify.com/actors/runs/${runId}` : 'https://console.apify.com/actors/runs';
  const datasetUrl = run.defaultDatasetId
    ? `https://console.apify.com/storage/datasets/${run.defaultDatasetId}`
    : runUrl;
  const buyerChargeUsd = Number(summary?.ppe?.actualBuyerChargeUsd);
  const base = { run, summary, runId, runUrl, datasetUrl, buyerChargeUsd };

  if (upper(summary.status) !== 'SUCCEEDED') {
    return { ...base, state: 'PARTIAL_OR_CAPPED', reason: `SUMMARY_STATUS_${upper(summary.status) || 'MISSING'}` };
  }
  if (!Number.isFinite(buyerChargeUsd) || buyerChargeUsd < 0) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'AUTHORITATIVE_BUYER_CHARGE_MISSING' };
  }
  const targetSummaries = Array.isArray(summary.targetSummaries) ? summary.targetSummaries : [];
  const targetErrors = Array.isArray(summary.targetErrors) ? summary.targetErrors : [];
  const observedTargets = new Set([
    ...targetSummaries.map((target) => target.queryId).filter(Boolean),
    ...targetErrors.map((target) => target.queryId).filter(Boolean),
  ]).size;
  if (!Number.isInteger(expectedTargetCount) || observedTargets !== expectedTargetCount) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'TARGET_RECONCILIATION_MISMATCH', coverage: targetSummaries };
  }
  if (targetErrors.length) {
    return { ...base, state: 'PARTIAL_OR_CAPPED', reason: 'TARGET_ERRORS_PRESENT', coverage: targetSummaries };
  }

  const normalizedRows = rows.filter((row) => row && typeof row === 'object' && Object.keys(row).length && !row.error);
  if (rows.some((row) => row?.error)) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'DATASET_READ_ERROR', coverage: targetSummaries };
  }
  const deduped = [];
  const seen = new Set();
  for (const row of normalizedRows) {
    const key = rowKey(row);
    if (seen.has(key)) continue;
    seen.add(key);
    deduped.push(row);
  }
  if (deduped.length !== Number(summary.outputRows)) {
    return {
      ...base,
      state: 'WORKFLOW_NODE_FAILED',
      reason: `DATASET_COUNT_MISMATCH_EXPECTED_${summary.outputRows}_GOT_${deduped.length}`,
      coverage: targetSummaries,
    };
  }

  const incomplete = targetSummaries.some((target) => {
    const coverage = upper(target.coverageStatus);
    return !COMPLETE_COVERAGE.has(coverage) || (coverage === 'EMPTY' && target.sourceExhausted !== true);
  });
  const baselineTargets = targetSummaries.filter((target) => target?.change && target.change.previousScopeMatched === false);
  if (baselineTargets.length) {
    return {
      ...base,
      state: 'BASELINE_CREATED',
      reason: 'FIRST_CHANGES_SCOPE',
      coverage: targetSummaries,
      rows: deduped,
      baselineTargetCount: baselineTargets.length,
      coverageComplete: !incomplete && summary?.ppe?.deliveryEventLimitReached !== true,
    };
  }
  if (incomplete || summary?.ppe?.deliveryEventLimitReached === true) {
    return { ...base, state: 'PARTIAL_OR_CAPPED', reason: 'COVERAGE_NOT_COMPLETE', coverage: targetSummaries, rows: deduped };
  }

  const counts = sumChangeCounts(targetSummaries);
  const changedCount = counts.NEW + counts.UPDATED + counts.ENDED;
  const allVerifiedEmpty = targetSummaries.length > 0
    && targetSummaries.every((target) => upper(target.coverageStatus) === 'EMPTY' && target.sourceExhausted === true);
  if (!deduped.length && allVerifiedEmpty) {
    return { ...base, state: 'EMPTY_VERIFIED', reason: 'ALL_TARGETS_EXHAUSTED_EMPTY', coverage: targetSummaries, rows: [], counts };
  }
  if (changedCount === 0) {
    return { ...base, state: 'UNCHANGED_VERIFIED', reason: 'COMPLETE_COVERAGE_NO_CHANGES', coverage: targetSummaries, rows: deduped, counts };
  }
  return { ...base, state: 'CHANGES_DELIVERED', reason: 'VERIFIED_CHANGE_ROWS', coverage: targetSummaries, rows: deduped, counts };
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function money(value) {
  const number = Number(value);
  if (!Number.isFinite(number) || number < 0) return 'unavailable';
  return number >= 1 ? `$${number.toFixed(2)}` : `$${number.toFixed(4).replace(/0+$/, '').replace(/\.$/, '.00')}`;
}

function eventLabel(name) {
  return ({
    actor_start: 'start',
    baseline_ad_result: 'baseline result',
    changes_ad_result: 'tracked result',
  })[name] ?? String(name).replace(/_/g, ' ');
}

function renderMetaReceipt(result = {}) {
  const label = {
    BASELINE_CREATED: 'Baseline created',
    CHANGES_DELIVERED: 'Verified competitor-ad changes',
    UNCHANGED_VERIFIED: 'No changes — verified',
    EMPTY_VERIFIED: 'No matching ads — verified empty',
    PARTIAL_OR_CAPPED: 'Coverage incomplete',
    ACTOR_FAILED_OR_ABORTED: 'Actor run failed or stopped',
    WORKFLOW_NODE_FAILED: 'Workflow could not verify the result',
  }[result.state] ?? 'Meta Ads monitoring result';
  const lines = [`<b>${escapeHtml(label)}</b>`];
  if (result.state === 'BASELINE_CREATED') {
    lines.push('The first Changes run established a comparison baseline. Current ads are not labeled as newly launched.');
    if (result.coverageComplete === false) {
      lines.push('At least one baseline target was capped or incomplete; future missing ads cannot be treated as safely ended until a complete comparison exists.');
    }
  } else if (result.state === 'CHANGES_DELIVERED') {
    const counts = result.counts ?? {};
    lines.push(`NEW ${counts.NEW ?? 0} · UPDATED ${counts.UPDATED ?? 0} · ENDED ${counts.ENDED ?? 0}`);
  } else if (result.state === 'PARTIAL_OR_CAPPED') {
    lines.push('No “nothing changed” or safe-ended claim was made because at least one target was incomplete, capped, or challenged.');
  } else if (result.state === 'WORKFLOW_NODE_FAILED' || result.state === 'ACTOR_FAILED_OR_ABORTED') {
    lines.push(`Reason: <code>${escapeHtml(result.reason ?? 'UNKNOWN')}</code>`);
  }
  if (Number.isFinite(Number(result.buyerChargeUsd))) {
    lines.push(`Exact Actor charge: <b>${escapeHtml(money(result.buyerChargeUsd))}</b>`);
  } else {
    lines.push('Exact Actor charge: unavailable — inspect the run before relying on this report.');
  }
  const chargedCounts = result?.summary?.ppe?.chargedCounts ?? {};
  const effectivePrices = result?.summary?.ppe?.effectivePricesUsd ?? {};
  const chargedEvents = Object.entries(chargedCounts)
    .filter(([, count]) => Number(count) > 0)
    .map(([name, count]) => {
      const price = Number(effectivePrices[name]);
      return `${eventLabel(name)} ${Number(count)}${Number.isFinite(price) ? ` @ ${money(price)}` : ''}`;
    });
  if (chargedEvents.length) lines.push(`Charged events: ${escapeHtml(chargedEvents.join(' · '))}`);
  if (Array.isArray(result.coverage) && result.coverage.length) {
    const zeroRows = result.coverage.filter((target) => Number(target.rows) === 0);
    const zeroIds = zeroRows.map((target) => String(target.queryId ?? '').slice(0, 8)).filter(Boolean);
    lines.push(
      `Coverage: ${result.coverage.length} target${result.coverage.length === 1 ? '' : 's'}`
      + (zeroRows.length ? ` · zero-row ${zeroRows.length}${zeroIds.length ? ` (${escapeHtml(zeroIds.slice(0, 3).join(', '))})` : ''}` : ''),
    );
  }
  if (result.runId) lines.push(`Run ID: <code>${escapeHtml(result.runId)}</code>`);
  return {
    message: lines.join('\n\n'),
    messageKind: ['WORKFLOW_NODE_FAILED', 'ACTOR_FAILED_OR_ABORTED', 'PARTIAL_OR_CAPPED'].includes(result.state) ? 'failure' : 'report',
    resultState: result.state,
    buyerChargeUsd: Number.isFinite(Number(result.buyerChargeUsd)) ? Number(result.buyerChargeUsd) : null,
    runId: result.runId ?? null,
    runUrl: result.runUrl ?? 'https://console.apify.com/actors/runs',
    datasetUrl: result.datasetUrl ?? result.runUrl ?? 'https://console.apify.com/actors/runs',
  };
}

const META_V2_LIMITS = Object.freeze({ maxTargets: MAX_TARGETS, maxRows: MAX_ROWS, pageSize: PAGE_SIZE });


return [{ json: preflightMetaConfig($input.first().json) }];

